namespace {
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
void until(const std::function<bool()>& f,const char* why,int ms=12000){QElapsedTimer t;t.start();while(!f()&&t.elapsed()<ms)QTest::qWait(10);check(f(),why);}
template<class T>T* find(QWidget& w,const char* name){auto* p=w.findChild<T*>(name);check(p,name);return p;}
void text(QWidget& w,const char* name,const QString& v){find<QLineEdit>(w,name)->setText(v);}
void click(QWidget& w,const char* name){auto* b=find<QPushButton>(w,name);check(b->isEnabled(),name);b->click();}
JsonDXX rpc(TcpClientDXX& c,const QString& type,const JsonDXX& data){QString id;JsonDXX out;bool done=false;auto con=QObject::connect(&c,&TcpClientDXX::responseReceived,[&](const JsonDXX& r){if(QString::fromStdString(r["request_id"].text())==id){out=r;done=true;}});id=c.request(type,data);until([&]{return done;},"real server RPC timeout");QObject::disconnect(con);check(out["success"].boolean(),"real server RPC failed");return out["data"];}
std::string display(const JsonDXX& a,const char* service){for(auto s:a["services"].items())if(s["service_type"].text()==service)return s["display_id"].text();throw std::runtime_error("display ID missing");}
void reachable(QWidget& window,QWidget* target){check(target->isVisible(),"bottom action must be visible");for(auto* p=target->parentWidget();p;p=p->parentWidget())if(auto* area=qobject_cast<QScrollArea*>(p))area->ensureWidgetVisible(target,4,4);QTest::qWait(20);const QRect r(target->mapTo(&window,QPoint()),target->size());check(window.rect().contains(r),"bottom action must fit inside exact window geometry");for(auto* p=target->parentWidget();p;p=p->parentWidget())if(auto* area=qobject_cast<QScrollArea*>(p))check(area->viewport()->rect().contains(QRect(target->mapTo(area->viewport(),QPoint()),target->size())),"bottom action must be reachable inside scroll viewport");}
void login(LoginWindowDXX& w,const QString& name){text(w,"loginName",name);text(w,"loginPassword","Mvp5TestPassword!");click(w,"loginSubmit");until([&]{return find<QPushButton>(w,"logoutButton")->isVisible();},"login real account");}
void snapshot(QWidget& w,const QString& dir,const QString& name){if(!dir.isEmpty()){QDir().mkpath(dir);check(w.grab().save(QDir(dir).filePath(name+".png")),"save screenshot");}}
}
